for (const n of base.notas || []) {
  const key = (n.proveedor || '-') + '|' + (n.nota || '-');
  const all = (allByKey[key] || []).slice(0, 36);
  n.bolsones = all.map(b => {
    const usedParte = (usadosPorNota[key] || {})[b.id] || (usadosPorNota[key] || {})[b.lote] || '';
    return {...b, usado_rama: !!usedParte, parte_usado: usedParte};
  });
  n.partes_destino = [...new Set(n.bolsones.map(b => b.parte || b.parte_usado).filter(Boolean))].join(', ');
}
base.notas_unicas = base.notas;
base.resumen.notas_total_items = base.notas.reduce((a,n)=>a+(n.total_items||0),0);
base.resumen.notas_total_kg = Math.round(base.notas.reduce((a,n)=>a+(n.total_kg||0),0)*10)/10;
base.resumen.notas_libres_items = base.notas.reduce((a,n)=>a+(n.restantes_items||0),0);
msg.base = base;
msg.topic = `
SELECT REPLACE(TRIM(Cat11), 'OUT ', '') AS parte_origen, ID_Bolson, NroLote, Fecha, Hora, DATEDIFF(CURDATE(), Fecha) AS dias, UnidadMedida, kilos, Maquina, Operador, Materiales, Description, Cat11
FROM TiposDeMovimiento
WHERE Cat11 IN (${base.gen1.map(p=>`'OUT ${p.parte}'`).join(',')})
  AND TiposDeMovimiento <> 'ERROR_REGISTRO'
  AND COALESCE(kilos, 0) > 0
ORDER BY Fecha ASC, Hora ASC
LIMIT 800;
`;
return msg;
